/**
 * Real ERC-8004 identity-registry logs from Ethereum, Base and Arc (the registry is the proxy at the one address, 0x8004a169..a432,
 * on all three), recorded on 2026-10-20, with the facts a decode must produce. The `expected` blocks were computed independently, by a
 * Python decode of the same bytes (the ABI string, SHA-256 of the raw URI, the https host, the inline JSON name), never by the code
 * under test. What each chain's recording holds: Ethereum, an empty URI, a web link, inline JSON with a name and a raw JSON string (an
 * unrecognized scheme); Base, an IPFS link, a web link, inline JSON with a name and an empty URI; Arc, a web link (the registry's
 * first event), two IPFS links (one replaced later) and inline JSON with a name. Each has the mint Transfer of every registration,
 * real URIUpdated logs, and a real change-of-hands Transfer.
 *
 * Monad's recording was made on 2026-11-01 from a read of the registry's whole history (docs/monad-erc8004-2026-11-01.md): a web link, a
 * web link whose agent later replaced it twice and handed the token on, inline JSON with a name, an empty URI, an IPFS link and a raw JSON
 * string (an unrecognized scheme). Its `refusals` hold the answer Alchemy gave to a window of 6,000,000 blocks that held more than 10,000 logs.
 *
 * Gnosis's recording was made on 2026-11-06 from a read of the registry's whole history (docs/gnosis-erc8004-2026-11-06.md): a web link from the
 * launch burst, a web link whose token was handed to another wallet and whose link was replaced, a web link that became a second web link, then
 * inline JSON, then an IPFS link, inline JSON with a name that was later replaced by an IPFS link, inline JSON with a name, an empty
 * URI and an empty URI that was set later, and an IPFS link. Its `refusals` hold the answer Alchemy gave to a window of 50,000 blocks, wider
 * than the 10,000 its plan answers.
 *
 * The logs were screened before they were chosen: none of the URIs or inline JSON holds an IP address, an email-like string, a
 * credential in a URL or a secret-looking word. Nothing about a provider's address is here. `refusals` are the answers a provider
 * gave to a window that was too wide, as it sent them (status and body); Arc's node never refused a window, so it has none.
 * A 429 is not recorded: the client reads only its status, so the tests send one with an empty body.
 */
export type ChainFixtureLog = Record<string, unknown>;

type ChainFixtureExpected = {
  agentId: string;
  owner: string;
  blockNumber: number;
  logIndex: number;
  uriKind: "web" | "ipfs" | "inline-json" | "empty" | "other";
  uriLength: number;
  profileUriHash: string;
  locatorHost: string | null;
  inlineName: string | null;
  truncated: boolean;
};

type ChainFixtureUpdate = {
  label: string;
  log: ChainFixtureLog;
  agentId: string;
  blockNumber: number;
  logIndex: number;
  newKind: string;
  uriLength: number;
  locatorHost: string | null;
  profileUriHash: string;
  inlineName: string | null;
};

export type ChainFixtures = {
  protocol: string;
  /** What `eth_chainId` answered, as recorded. */
  chainId: string;
  /** The finalized block as recorded, cut to the three fields that matter. */
  finalized: { number: string; hash: string; timestamp: string };
  registered: Record<string, { log: ChainFixtureLog; expected: ChainFixtureExpected }>;
  /** The mint Transfer of each registration above, by agent id. */
  mints: Record<string, ChainFixtureLog>;
  secondary: { log: ChainFixtureLog; agentId: string; from: string; to: string; blockNumber: number; logIndex: number };
  uriUpdates: ChainFixtureUpdate[];
  refusals: Array<{ label: string; status: number; body: unknown }>;
};

